from taf.nms.nom.schemas.base import SchemaObject, SchemaField, SchemaObjects


class InlineResponse200(SchemaObject):
    ne_sw_version = SchemaField(name="ne_sw_version", not_null=True)
    ne_type = SchemaField(name="ne_type", not_null=True)

    def __init__(self, ne_sw_version, ne_type):
        self.ne_sw_version = ne_sw_version
        self.ne_type = ne_type
        super(InlineResponse200, self).__init__()


class InlineResponses200(SchemaObjects):
    schema = InlineResponse200
